const validCompany=v=>/^[A-Za-z0-9._:-]{2,128}$/.test(clean(v,128));
const legacy=['tenant_id','tenant_company_id','tenant_company','tenant','tenantCompanyId','organisation_id','organization_id','workspace_tenant_id'];
function noLegacy(v,path='handover'){if(!v||typeof v!=='object')return;if(Array.isArray(v)){v.forEach((x,i)=>noLegacy(x,`${path}[${i}]`));return;}for(const [k,x] of Object.entries(v)){if(legacy.includes(k))throw new Error(`legacy-company-boundary:${path}.${k}`);noLegacy(x,`${path}.${k}`);}}
