  if(findings.some(x=>!x.evidence_backed))blockers.push('finding-evidence-required');
  if(accepted.some(x=>!x.evidence_refs.length&&!x.decision_ref))blockers.push('accepted-recommendation-evidence-required');
  if(unresolved_risks.some(x=>!x.owner_ref))blockers.push('unresolved-risk-owner-required');
  if(required_capabilities.some(x=>!x.owner_ref))blockers.push('required-capability-owner-required');
  if(!commissioning_gates.length)blockers.push('commissioning-gates-required');
  if(commissioning_gates.some(g=>g.required&&!g.passed&&!g.waived))blockers.push('commissioning-gates-incomplete');
