 assertCompany(spec.processes,company_id,'process');assertCompany(spec.people,company_id,'person');assertCompany(spec.systems,company_id,'system');assertCompany(spec.devices,company_id,'device');assertCompany(spec.documents,company_id,'document');assertCompany(spec.risks,company_id,'risk');assertCompany(spec.required_capabilities,company_id,'capability');
 const steps=[];
 steps.push(step('review:discovery','DISCOVERY_REVIEW','Review accepted discovery and handover evidence',[],{execution_class:'REVIEW_ONLY',rollback_required:false,evidence_refs:[discovery.discovery_id,spec.source_handover_id]}));
