 for(const x of arr(spec.required_capabilities).slice().sort((a,b)=>clean(a.capability_id).localeCompare(clean(b.capability_id))))steps.push(step(stableId('capability',x.capability_id),'CAPABILITY_PREPARATION',`Prepare capability ${clean(x.capability_id,220)}`,[policyStep],{target_ref:x.capability_id,evidence_refs:x.evidence_refs,capability_refs:[x.capability_id]}));
 for(const x of arr(spec.people).slice().sort((a,b)=>clean(a.id).localeCompare(clean(b.id))))steps.push(step(stableId('workforce',x.id),'WORKFORCE_ROLE_SETUP',`Prepare workforce actor ${clean(x.name||x.id,300)}`,[policyStep],{target_ref:x.id,evidence_refs:x.evidence_refs}));
 for(const x of arr(spec.systems).slice().sort((a,b)=>clean(a.id).localeCompare(clean(b.id))))steps.push(step(stableId('integration',x.id),'INTEGRATION_CONFIGURATION',`Configure integration ${clean(x.name||x.id,300)}`,[policyStep],{target_ref:x.id,evidence_refs:x.evidence_refs}));
 for(const x of arr(spec.devices).slice().sort((a,b)=>clean(a.id).localeCompare(clean(b.id))))steps.push(step(stableId('device',x.id),'DEVICE_CONFIGURATION',`Prepare device ${clean(x.name||x.id,300)}`,[policyStep],{target_ref:x.id,evidence_refs:x.evidence_refs}));
