 steps.push(step('prepare:rollback','ROLLBACK_PREPARATION','Verify rollback, uninstall and recovery procedures',buildIds,{execution_class:'REVIEW_ONLY',rollback_required:false}));
 const commissionDeps=['verify:integration','prepare:rollback'];
 for(const g of arr(spec.commissioning_gates))if(clean(g.state,30).toUpperCase()!=='COMPLETE'&&clean(g.state,30).toUpperCase()!=='PASSED')blockers.push(`commissioning-gate:${clean(g.gate_id||g.title,160)}`);
 for(const r of arr(spec.risks))if(!['CLOSED','RESOLVED','ACCEPTED'].includes(clean(r.state,30).toUpperCase())&&!r.owner_ref)blockers.push(`unowned-risk:${clean(r.risk_id,160)}`);
